secret=$(head -c 16 /dev/urandom | xxd -ps) # 生成一个16字节的随机字符串，并将其转换为十六进制表示形式，作为MTProxy的secrettag="12345678901234567890121231231231" # 生成一个32字节的随机字符串，作为MTProxy的tagdomain="cloudflare.com" # 设置MTProxy的域名为cloudflare.comecho "secret: $secret, tag: $tag, domain: $domain" # checkdocker pull ellermister/nginx-mtproxy:latest # 拉取最新的ellermister/nginx-mtproxy镜像docker run --name nginx-mtproxy -d \  --restart always \  -p 443:443 \  -e secret="$secret" \  -e domain="$domain" \  -e ip_white_list=OFF \  ellermister/nginx-mtproxy:latestdocker logs nginx-mtproxy # check the# docker update --restart=always nginx-mtproxy# docker inspect nginx-mtproxy | grep 443# sudo ss -antp | grep 443